fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // The two input vectors must have the same length.
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    // Consume both vectors and zip them, performing bitwise AND on each pair,
    // then collect the results into a new Vec<u8>.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x & y)
     .collect()
}

